CREATE TABLE IF NOT EXISTS monitor_sources (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL UNIQUE,parser TEXT NOT NULL DEFAULT 'text',enabled BOOLEAN NOT NULL DEFAULT true,last_checked_at TIMESTAMPTZ,last_fingerprint TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS monitor_snapshots (id BIGSERIAL PRIMARY KEY,source_id BIGINT NOT NULL REFERENCES monitor_sources(id) ON DELETE CASCADE,fingerprint TEXT NOT NULL,content TEXT NOT NULL,fetched_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,fingerprint));
CREATE TABLE IF NOT EXISTS monitor_proposals (id BIGSERIAL PRIMARY KEY,source_id BIGINT NOT NULL REFERENCES monitor_sources(id) ON DELETE CASCADE,previous_snapshot_id BIGINT REFERENCES monitor_snapshots(id),current_snapshot_id BIGINT NOT NULL REFERENCES monitor_snapshots(id),diff TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),reviewed_by UUID REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS monitor_proposals_status_idx ON monitor_proposals(status,created_at DESC);
CREATE TABLE IF NOT EXISTS notification_preferences (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,email_enabled BOOLEAN NOT NULL DEFAULT true,digest_enabled BOOLEAN NOT NULL DEFAULT true,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_deliveries (id BIGSERIAL PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,proposal_id BIGINT NOT NULL REFERENCES monitor_proposals(id) ON DELETE CASCADE,email TEXT NOT NULL,delivered_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,proposal_id));
